import comments from "@eslint-community/eslint-plugin-eslint-comments/configs";
import js from "@eslint/js";
import prettier from "eslint-config-prettier/flat";
import vue from "eslint-plugin-vue";
import { defineConfig, globalIgnores } from "eslint/config";
import globals from "globals";
import tseslint from "typescript-eslint";

// ESLint (`pnpm lint`) checks code quality; Prettier owns formatting, so the
// last entry turns off every rule that would disagree with it.
export default defineConfig(
  // Build output and generated files. node_modules/ is always ignored. The
  // Rust side (src-tauri/) has rustfmt and clippy instead.
  globalIgnores(["dist/", "coverage/", "src-tauri/"]),

  js.configs.recommended,
  tseslint.configs.recommended,

  // Vue style guide priorities A and B (AGENTS.md, "Conventions"), plus C.
  vue.configs["flat/recommended"],
  {
    files: ["**/*.vue"],
    languageOptions: {
      // Parses `<script setup lang="ts">` with TypeScript, so the
      // typescript-eslint rules apply inside components too.
      parserOptions: { parser: tseslint.parser },
    },
    rules: {
      // Components use `<script setup lang="ts">` (AGENTS.md, "Conventions").
      "vue/block-lang": ["error", { script: { lang: "ts" } }],
      "vue/component-api-style": ["error", ["script-setup"]],
      // `v-html` inserts a string as HTML without escaping it, the main way
      // to open an XSS hole in a Vue app; in the Tauri webview, injected
      // script could call the app's IPC. `flat/recommended` only warns.
      "vue/no-v-html": "error",
      // TypeScript already reports undefined names, and knows the browser
      // and Vue globals that this rule would need to be told about.
      "no-undef": "off",
    },
  },

  // No hard-coded text in templates (AGENTS.md): what people read or hear
  // goes through vue-i18n, as `{{ t("key") }}` or `:title="t('key')"`
  // (CONTRIBUTING.md, "Adding text to the app"). A string literal bound to
  // an attribute, such as `:title="'Stop'"`, is not reported.
  {
    files: ["**/*.vue"],
    rules: {
      // Text in elements, and the static value of the attributes below.
      "vue/no-bare-strings-in-template": [
        "error",
        {
          // Text made only of these characters and whitespace (including
          // `&nbsp;`) is a separator, the same in every language.
          allowlist: [":", "/", "·", "•", "-", "–", "—", "|", "(", ")"],
          // The attributes that people read or hear, on any element or
          // component (`placeholder` on shadcn-vue's `Input` too).
          attributes: {
            "/.+/": [
              "title",
              "aria-label",
              "aria-description",
              "aria-placeholder",
              "aria-roledescription",
              "aria-valuetext",
              "placeholder",
              "alt",
            ],
          },
        },
      ],
      // A string literal shown with `{{ "text" }}`, which the rule above
      // does not see.
      "vue/no-useless-mustaches": "error",
    },
  },
  // Exempt from the two rules above, and only from them:
  // - src/dev/: the component gallery, which is not user-facing and is left
  //   out of production builds (src/App.vue);
  // - src/components/ui/: components generated by the shadcn-vue CLI, kept
  //   exactly as it writes them (see below). Some have English text for
  //   screen readers, such as "Close" in dialogs and "Toggle Sidebar",
  //   which the screens that use them must translate (CONTRIBUTING.md,
  //   "Adding text to the app").
  {
    files: ["src/dev/**", "src/components/ui/**"],
    rules: {
      "vue/no-bare-strings-in-template": "off",
      "vue/no-useless-mustaches": "off",
    },
  },

  // Unused function parameters are reported here rather than by TypeScript
  // (tsconfig.app.json sets `noUnusedParameters: false`, because generated
  // code trips it; see the next entry). `args: "all"` and the `_` prefix
  // match what TypeScript's option reports and accepts.
  {
    rules: {
      "@typescript-eslint/no-unused-vars": [
        "error",
        { args: "all", argsIgnorePattern: "^_" },
      ],
    },
  },

  // Components generated by the shadcn-vue CLI (CONTRIBUTING.md, "Adding
  // shadcn-vue components"). They are kept exactly as the CLI writes them,
  // so that updating one is a matter of running the CLI again (AGENTS.md:
  // edited only for tokens or variants). Their style differs from the rest of the
  // app in ways these rules report, so only these rules are off, and only
  // here; everything else still applies.
  {
    files: ["src/components/ui/**"],
    rules: {
      // Optional props without a default are undefined, as intended.
      "vue/require-default-prop": "off",
      // Single-word names (Button, Card, ...) are the library's API.
      "vue/multi-word-component-names": "off",
      // chart/ types Unovis' untyped data with `any`.
      "@typescript-eslint/no-explicit-any": "off",
      // chart/ChartLegendContent.vue destructures a value it does not use.
      "@typescript-eslint/no-unused-vars": "off",
    },
  },

  {
    files: ["src/**", "tests/**"],
    languageOptions: { globals: globals.browser },
  },
  {
    files: ["*.config.ts", "tests/**"],
    languageOptions: { globals: globals.node },
  },

  // Directive comments: every `eslint-disable` must say why (AGENTS.md:
  // lints are not suppressed without a comment explaining why), as in
  // `// eslint-disable-next-line <rule> -- <reason>`.
  comments.recommended,
  {
    rules: {
      "@eslint-community/eslint-comments/require-description": "error",
    },
  },
  {
    linterOptions: { reportUnusedDisableDirectives: "error" },
  },

  prettier,
);
